    // ─────────── فصل ۱: شیطان در مسکو ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The Devil in Moscow", titlePersian = "شیطان در مسکو",
        paragraphs = listOf(
            StoryParagraph("It was a hot spring day in Moscow, the kind of day when the asphalt melts and the air smells of lime and dust.", "روز گرم بهاری در مسکو بود، همان نوع روزی که آسفالت آب می‌شود و هوا بوی آهک و غبار دارد."),
            StoryParagraph("The sun had been beating down on the city since early morning, and the people of Moscow were tired, and irritable, and full of complaints.", "خورشید از اول صبح بر شهر می‌کوبید و مردم مسکو خسته و زودرنج و پر از شکایت بودند."),
            StoryParagraph("In the shade of the lime trees at Patriarch's Ponds, two men were sitting on a bench, and they were arguing about religion.", "در سایه درختان آهک نزدیک برکه‌های پاتریارش، دو مرد روی نیمکتی نشسته بودند و درباره دین بحث می‌کردند."),
            StoryParagraph("The first was Mikhail Alexandrovich Berlioz, the editor of a thick literary journal, a man of importance and small imagination.", "اولی میخائیل آلکساندراویچ برلیوز بود، سردبیر مجله ادبی مهمی، مردی با اهمیت و تخیل کوچک."),
            StoryParagraph("The second was Ivan Nikolayevich Ponyryov, a young poet who wrote under the pen name Bezdomny, which means 'the homeless one.'", "دومی ایوان نیکولایویچ پونیریوف بود، شاعر جوانی که با نام مستعار بزدومنی می‌نوشت، که یعنی «بی‌خانه»."),
            StoryParagraph("Berlioz was lecturing the young poet about the importance of atheism, about the need to prove, in verse, that Jesus Christ had never existed.", "برلیوز داشت به شاعر جوان درباره اهمیت بی‌خدایی درس می‌داد، درباره نیاز به اثبات، در شعر، که عیسی مسیح هرگز وجود نداشته."),
            StoryParagraph("'You have written a poem about Jesus,' Berlioz said, 'but the poem is wrong. Jesus never existed. He was a myth, an invention, a fairy tale.'", "برلیوز گفت: «شعری درباره عیسی نوشته‌ای، اما شعر اشتباه است. عیسی هرگز وجود نداشت. او افسانه بود، اختراع، قصه پریان.»"),
            StoryParagraph("Ivan was not convinced; he had read the Gospels; he had felt, in those ancient texts, something that seemed to him to be true.", "ایوان قانع نشد؛ انجیل‌ها را خوانده بود؛ در آن متون کهن چیزی حس کرده بود که به نظرش راستین می‌آمد."),
            StoryParagraph("'But the sources,' Berlioz insisted, 'the historical sources, the Roman historians — they say nothing about Jesus.'", "برلیوز اصرار کرد: «اما منابع، منابع تاریخی، مورخان رومی — هیچ چیزی درباره عیسی نمی‌گویند.»"),
            StoryParagraph("And then, quite suddenly, a stranger joined them on the bench.", "و بعد، کاملاً ناگهانی، غریبه‌ای روی نیمکت به آن‌ها پیوست."),
            StoryParagraph("He was a tall man, dressed in an expensive grey suit, with a walking stick and a foreign-looking hat.", "مردی بلندقد بود، با کت و شلوار گران‌قیمت خاکستری، با عصایی و کلاهی به سبک خارجی."),
            StoryParagraph("His face was strangely memorable, and strangely unmemorable; his eyes were of two different colors, one black and one green.", "چهره‌اش به شکلی عجیب به‌یادماندنی و به شکلی عجیب فراموش‌شدنی بود؛ چشمانش دو رنگ متفاوت داشتند، یکی سیاه و یکی سبز."),
            StoryParagraph("'I beg your pardon,' the stranger said, 'but I could not help overhearing your conversation. It is a fascinating topic.'", "غریبه گفت: «عذر می‌خواهم، اما نتوانستم صحبت‌تان را نشنیده بگیرم. موضوع جذابی است.»"),
            StoryParagraph("'Who are you?' Berlioz asked, coldly.", "برلیوز سرد پرسید: «شما کی هستید؟»"),
            StoryParagraph("'I am a specialist in black magic,' the stranger said, and he smiled a thin, knowing smile.", "غریبه گفت: «متخصص جادوی سیاهم.» و لبخندی نازک و آگاهانه زد."),
            StoryParagraph("Berlioz was not amused; he was, in fact, annoyed; he did not like strangers, and he did not like conversations about magic.", "برلیوز خوشحال نشد؛ در واقع، آزرده شد؛ غریبه‌ها را دوست نداشت و گفتگو درباره جادو را هم."),
            StoryParagraph("'We were discussing religion,' he said, stiffly. 'I was explaining to my young friend that Jesus never existed.'", "گفت: «درباره دین بحث می‌کردیم. به دوست جوانم توضیح می‌دادم که عیسی هرگز وجود نداشت.»"),
            StoryParagraph("'Indeed?' the stranger said. 'How strange. I was present at the trial of Pontius Pilate, in Jerusalem, almost two thousand years ago.'", "غریبه گفت: «واقعاً؟ عجیب است. من در محاکمه پونتیوس پیلاطس بودم، در اورشلیم، نزدیک دو هزار سال پیش.»"),
            StoryParagraph("Berlioz laughed; he could not help it; the stranger's claim was so absurd that it was almost funny.", "برلیوز خندید؛ نمی‌توانست جلوی خودش را بگیرد؛ ادعای غریبه آنقدر پوچ بود که تقریباً خنده‌دار."),
            StoryParagraph("'Present at the trial? How? You are not yet fifty years old.'", "«در محاکمه حاضر بودید؟ چطور؟ شما هنوز پنجاه سالتان نیست.»"),
            StoryParagraph("'Age,' the stranger said, 'is a relative concept. Some men age faster than others; some, in fact, do not age at all.'", "غریبه گفت: «سن مفهومی نسبی است. بعضی مردان سریع‌تر پیر می‌شوند از بقیه؛ بعضی، در واقع، اصلاً پیر نمی‌شوند.»"),
            StoryParagraph("Berlioz was beginning to feel uneasy; there was something in the stranger's eyes that he did not like, something that seemed to be mocking him.", "برلیوز شروع کرد به حس ناآرامی؛ چیزی در چشمان غریبه بود که دوستش نداشت، چیزی که به نظر می‌رسید مسخره‌اش می‌کند."),
            StoryParagraph("'What is your name?' he asked.", "پرسید: «نامتان چیست؟»"),
            StoryParagraph("'My name,' said the stranger, 'is Woland. Professor Woland. And I am here in Moscow to study, among other things, the atheism of the Soviet people.'", "غریبه گفت: «نام من ولاند است. پروفسور ولاند. و اینجا در مسکو هستم تا، میان چیزهای دیگر، بی‌خدایی مردم شوروی را مطالعه کنم.»"),
            StoryParagraph("Ivan did not understand what was happening; he felt as if he were in a dream, a strange dream from which he could not wake.", "ایوان نمی‌فهمید چه اتفاقی می‌افتد؛ حس می‌کرد در خواب است، خوابی عجیب که نمی‌تواند از آن بیدار شود."),
            StoryParagraph("'But let me tell you about Pilate,' Woland said, and he began to speak, and his voice was suddenly different, deeper, richer, full of authority.", "ولاند گفت: «اما بگذارید درباره پیلاطس بگویم.» و شروع به صحبت کرد و صدایش ناگهان متفاوت شد، عمیق‌تر، غنی‌تر، پر از اقتدار."),
            StoryParagraph("He spoke of a morning in Jerusalem, of the fifth procurator of Judea, of a man named Pontius Pilate.", "از صبحی در اورشلیم گفت، از پنجمین والی یهودیه، از مردی به نام پونتیوس پیلاطس."),
            StoryParagraph("He spoke of a prisoner named Yeshua Ha-Notsri, of a trial, of a decision that would haunt Pilate for two thousand years.", "از زندانی به نام یشوع هانوتسری گفت، از محاکمه‌ای، از تصمیمی که دو هزار سال پیلاطس را تسخیر می‌کرد."),
            StoryParagraph("And as Woland spoke, the world seemed to fade away, and the ancient story became real, more real than the hot Moscow afternoon.", "و همانطور که ولاند صحبت می‌کرد، جهان به نظر محو می‌شد و داستان کهن حقیقی می‌شد، حقیقی‌تر از بعدازظهر گرم مسکو."),
            StoryParagraph("Berlioz and Ivan listened, and they could not stop listening; they were caught in the spell of the story, in the spell of the storyteller.", "برلیوز و ایوان گوش دادند و نمی‌توانستند از گوش دادن دست بکشند؛ در طلسم داستان گرفتار شده بودند، در طلسم داستان‌گو."),
            StoryParagraph("And when Woland had finished, he smiled again, and he said, 'But you, my dear Berlioz, do not believe in any of this.'", "و وقتی ولاند تمام کرد، دوباره لبخند زد و گفت: «اما شما، برلیوز عزیز، به هیچ‌کدام از اینها باور ندارید.»"),
            StoryParagraph("'Of course not,' Berlioz said. 'I am an educated man. I do not believe in fairy tales.'", "برلیوز گفت: «البته که نه. من مردی تحصیل‌کرده‌ام. به قصه‌های پریان باور ندارم.»"),
            StoryParagraph("'Then let me offer you a prophecy,' Woland said. 'This afternoon, you will die. You will be decapitated by a woman — a Russian woman, a member of the Komsomol.'", "ولاند گفت: «پس بگذارید پیشگویی‌ای به شما تقدیم کنم. این بعدازظهر می‌میرید. سرتان توسط زنی بریده می‌شود — زنی روس، عضو کومسومول.»"),
            StoryParagraph("Berlioz laughed; the prophecy was even more absurd than the rest of the stranger's talk.", "برلیوز خندید؛ پیشگویی حتی از بقیه حرف‌های غریبه پوچ‌تر بود."),
            StoryParagraph("'I have no intention of dying today,' he said. 'And I have never met a member of the Komsomol who would —'", "گفت: «قصد ندارم امروز بمیرم. و هرگز کومسومولی ندیده‌ام که—»"),
            StoryParagraph("But he stopped; for at that moment, a young woman in a red kerchief walked past, and she was carrying a bottle of sunflower oil.", "اما متوقف شد؛ زیرا در آن لحظه، زن جوانی با روسری سرخ از آنجا می‌گذشت و بطری روغن آفتابگردان حمل می‌کرد."),
            StoryParagraph("She tripped on a loose stone, and the bottle slipped from her hands, and the oil spilled onto the tram tracks.", "روی سنگی لق لیز خورد و بطری از دستانش لغزید و روغن روی ریل‌های تراموا ریخت."),
            StoryParagraph("'There,' Woland said, quietly. 'The oil is spilled. Now you know the rest.'", "ولاند آرام گفت: «آنجا. روغن ریخته شد. حالا بقیه‌اش را می‌دانید.»"),
            StoryParagraph("And then, just as suddenly as he had appeared, Woland was gone; he had simply walked away, without a word, without a glance.", "و بعد، همان‌قدر ناگهان که آمده بود، ولاند رفت؛ تنها راه رفته بود، بدون کلمه، بدون نگاهی."),
            StoryParagraph("Berlioz and Ivan sat on the bench, in silence, and they did not know what to say.", "برلیوز و ایوان در سکوت روی نیمکت نشستند و نمی‌دانستند چه بگویند."),
            StoryParagraph("'He is a madman,' Berlioz said, at last. 'Or a provocateur. Or both.'", "برلیوز سرانجام گفت: «دیوانه است. یا آشوبگر. یا هر دو.»"),
            StoryParagraph("'But the oil,' Ivan said. 'The oil was real. He predicted the oil.'", "ایوان گفت: «اما روغن. روغن واقعی بود. روغن را پیش‌بینی کرد.»"),
            StoryParagraph("'Coincidence,' Berlioz said. 'A trick. A very clever trick.'", "برلیوز گفت: «تصادف است. حقه‌ای است. حقه‌ای بسیار زیرکانه.»"),
            StoryParagraph("But Berlioz was not so certain as he pretended to be; he was, in fact, afraid.", "اما برلیوز آنقدر که تظاهر می‌کرد مطمئن نبود؛ در واقع، می‌ترسید."),
            StoryParagraph("He walked to the tram stop, and he waited for the tram, and he thought about the strange stranger.", "به ایستگاه تراموا رفت و منتظر تراموا ماند و به غریبه عجیب فکر کرد."),
            StoryParagraph("The tram came, and Berlioz stepped onto the tracks to cross, and he slipped on the oil.", "تراموا آمد و برلیوز به روی ریل‌ها قدم گذاشت تا رد شود و روی روغن لیز خورد."),
            StoryParagraph("He fell, and the tram could not stop, and the wheels passed over his neck, and his head was severed from his body.", "افتاد و تراموا نتوانست بایستد و چرخ‌ها از گردنش گذشتند و سرش از تنش جدا شد."),
            StoryParagraph("The prophecy was fulfilled; the impossible had happened; the world would never be the same.", "پیشگویی محقق شد؛ ناممکن اتفاق افتاده بود؛ جهان هرگز همان نمی‌شد."),
            StoryParagraph("And Ivan Bezdomny, the young poet, stood beside the body of his friend, and he did not know what to think, or what to feel, or what to do.", "و ایوان بزدومنی، شاعر جوان، کنار جسد دوستش ایستاد و نمی‌دانست چه فکر کند، یا چه حس کند، یا چه بکند."),
            StoryParagraph("He looked around for Woland, but Woland was gone; he looked for the woman with the oil, but she was gone; he looked for something that made sense, but there was nothing.", "اطراف را دنبال ولاند گشت اما ولاند رفته بود؛ دنبال زن با روغن گشت اما او هم رفته بود؛ دنبال چیزی گشت که منطقی باشد اما هیچ نبود."),
            StoryParagraph("And so the story began, with a decapitation and a prophecy, with a stranger and a madman, with the devil himself walking the streets of Moscow.", "و اینگونه داستان با سربریدن و پیشگویی آغاز شد، با غریبه‌ای و دیوانه‌ای، با خود شیطان در خیابان‌های مسکو قدم می‌زد."),
            StoryParagraph("Ivan ran; he ran through the streets, chasing shadows, chasing impossibilities; and as he ran, he began to lose his mind.", "ایوان دوید؛ در خیابان‌ها دوید، دنبال سایه‌ها، دنبال ناممکن‌ها؛ و همانطور که می‌دوید، شروع کرد به از دست دادن عقلش."),
            StoryParagraph("He would end up in a mental hospital, that very night, and there he would meet a man who would change his life.", "همان شب در بیمارستان روانی تمام می‌کرد و آنجا مردی را ملاقات می‌کرد که زندگی‌اش را تغییر می‌داد."),
            StoryParagraph("But that is the next part of the story; for now, there is only Berlioz, dead on the tracks, and Woland, wherever he has gone.", "اما آن بخش بعدی داستان است؛ برای اکنون، تنها برلیوز است، مرده روی ریل‌ها و ولاند، هر جا که رفته."),
            StoryParagraph("And the oil, still shining on the tram tracks, in the hot Moscow afternoon.", "و روغن، هنوز بر ریل‌های تراموا می‌درخشد، در بعدازظهر گرم مسکو.")
        )
    )

    // ─────────── فصل ۲: پونتیوس پیلاطس ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "Pontius Pilate", titlePersian = "پونتیوس پیلاطس",
        paragraphs = listOf(
            StoryParagraph("In the palace of Herod the Great, in Jerusalem, on the morning of the fourteenth day of the spring month of Nisan, Pontius Pilate, procurator of Judea, came out to the colonnade.", "در کاخ هرود بزرگ، در اورشلیم، در صبح چهاردهمین روز ماه بهار نیسان، پونتیوس پیلاطس، والی یهودیه، به ایوان ستون‌دار آمد."),
            StoryParagraph("He was a man of about forty-five, with a face that was both hard and tired, and with eyes that had seen too much of human cruelty.", "مردی حدوداً چهل و پنج ساله بود، با چهره‌ای هم‌زمان سخت و خسته و با چشمانی که بی‌رحمی انسانی را بیش از حد دیده بود."),
            StoryParagraph("He had served in the army, had fought in wars, had grown accustomed to death; but there was still something in him that flinched at suffering.", "در ارتش خدمت کرده بود، در جنگ‌ها جنگیده بود، به مرگ عادت کرده بود؛ اما هنوز چیزی در او بود که از رنج برمی‌خاست."),
            StoryParagraph("His head ached, as it often did in this hateful city, with its dry heat and its dusty streets and its endless religious quarrels.", "سرش درد می‌کرد، همانطور که اغلب در این شهر نفرت‌انگیز می‌کرد، با گرمای خشکش و خیابان‌های غبارآلودش و جدال‌های دینی بی‌پایانش."),
            StoryParagraph("'Bring the prisoner,' he said, and his voice was quiet, but it carried.", "گفت: «زندانی را بیاورید.» و صدایش آرام بود اما شنیده می‌شد."),
            StoryParagraph("And they brought him, the prisoner, the man they called Yeshua Ha-Notsri.", "و آوردندش، زندانی، مردی که یشوع هانوتسری صدایش می‌زدند."),
            StoryParagraph("He was a small man, in an old and torn robe, with bare feet and bruised hands, and with a face that was strangely peaceful.", "مردی کوچک بود، با جامه‌ای کهنه و پاره، با پاهای برهنه و دست‌های کبود و با چهره‌ای به شکلی عجیب آرام."),
            StoryParagraph("He did not look like a criminal; he looked like a wanderer, a dreamer, a philosopher.", "شبیه مجرم نبود؛ شبیه سرگردانی بود، رؤیاپردازی، فیلسوفی."),
            StoryParagraph("'Who are you?' Pilate asked.", "پیلاطس پرسید: «تو کی هستی؟»"),
            StoryParagraph("'My name is Yeshua,' the prisoner said. 'I am a wandering philosopher. I have no home, no family, no possessions.'", "زندانی گفت: «نام من یشوع است. فیلسوفی سرگردانم. خانه‌ای ندارم، نه خانواده، نه دارایی.»"),
            StoryParagraph("'What do you teach?' Pilate asked.", "پیلاطس پرسید: «چه تعلیم می‌دهی؟»"),
            StoryParagraph("'I teach that all men are good,' Yeshua said. 'I teach that the kingdom of truth and justice will come, and that all men will be free.'", "یشوع گفت: «تعلیم می‌دهم که همه انسان‌ها خوبند. تعلیم می‌دهم که پادشاهی حقیقت و عدالت خواهد آمد و همه انسان‌ها آزاد خواهند شد.»"),
            StoryParagraph("'But you have been accused,' Pilate said, 'of inciting the people to destroy the temple, of speaking against the emperor, of blasphemy.'", "پیلاطس گفت: «اما تو متهم شده‌ای که مردم را به نابود کردن معبد تحریک کرده‌ای، علیه امپراتور سخن گفته‌ای، کفر گفته‌ای.»"),
            StoryParagraph("'These accusations are false,' Yeshua said. 'I have never said such things. I have only spoken of love and truth.'", "یشوع گفت: «این اتهامات دروغ است. هرگز چنین چیزهایی نگفته‌ام. تنها از عشق و حقیقت سخن گفته‌ام.»"),
            StoryParagraph("Pilate looked at him, and there was something in the prisoner's eyes that troubled him, something that he did not understand.", "پیلاطس نگاهش کرد و چیزی در چشمان زندانی بود که ناراحتش می‌کرد، چیزی که نمی‌فهمید."),
            StoryParagraph("'And what is truth?' Pilate asked, and the question was not mockery, but genuine curiosity.", "پیلاطس پرسید: «و حقیقت چیست؟» و پرسش نه ریشخند بود، بلکه کنجکاوی اصیل."),
            StoryParagraph("Yeshua looked at him, and he smiled a small, sad smile.", "یشوع نگاهش کرد و لبخندی کوچک و غمگین زد."),
            StoryParagraph("'Truth,' he said, 'is that your head aches, and that you are tired, and that you are lonely, and that you wish you were somewhere else.'", "گفت: «حقیقت این است که سرت درد می‌کند و خسته‌ای و تنهایی و آرزو داری جای دیگری باشی.»"),
            StoryParagraph("Pilate was startled; he had not expected such an answer; he had not expected the prisoner to see through him so completely.", "پیلاطس جا خورد؛ انتظار چنین پاسخی را نداشت؛ انتظار نداشت زندانی اینقدر کامل از او بگذرد."),
            StoryParagraph("'How do you know this?' he asked.", "پرسید: «از کجا این را می‌دانی؟»"),
            StoryParagraph("'Because I see you,' Yeshua said. 'I see what you are, and I see what you could be. And I see that you are afraid.'", "یشوع گفت: «چون تو را می‌بینم. می‌بینم چه هستی و می‌بینم چه می‌توانی باشی. و می‌بینم که می‌ترسی.»"),
            StoryParagraph("'Afraid? Of what?' Pilate asked, and his voice was sharp.", "پیلاطس پرسید: «بترسم؟ از چه؟» و صدایش تیز بود."),
            StoryParagraph("'Of the crowd,' Yeshua said. 'Of the high priests. Of the emperor. Of yourself.'", "یشوع گفت: «از جمعیت. از کاهنان اعظم. از امپراتور. از خودت.»"),
            StoryParagraph("Pilate was silent for a long moment, and he looked at the prisoner, and he felt something that he had not felt in years: the possibility of understanding.", "پیلاطس لحظه‌ای طولانی ساکت بود و به زندانی نگاه کرد و چیزی حس کرد که سال‌ها حس نکرده بود: امکان فهم."),
            StoryParagraph("'You are a strange man,' he said, at last. 'And I do not want to kill you.'", "سرانجام گفت: «مرد عجیبی هستی. و نمی‌خواهم بکشمت.»"),
            StoryParagraph("'Then do not kill me,' Yeshua said. 'Let me go. I have done nothing wrong.'", "یشوع گفت: «پس نکش. رهایم کن. کار اشتباهی نکرده‌ام.»"),
            StoryParagraph("But Pilate could not let him go; the high priests demanded his death; the crowd demanded his death; the emperor would demand his death.", "اما پیلاطس نمی‌توانست رهایش کند؛ کاهنان اعظم مرگش را می‌خواستند؛ جمعیت مرگش را می‌خواست؛ امپراتور مرگش را می‌خواست."),
            StoryParagraph("'You have spoken against the emperor,' Pilate said, and his voice was heavy with sorrow. 'That is a crime. It carries the death penalty.'", "پیلاطس گفت: «علیه امپراتور سخن گفته‌ای.» و صدایش از اندوه سنگین بود. «این جنایت است. مجازاتش مرگ است.»"),
            StoryParagraph("'But I did not speak against the emperor,' Yeshua said. 'I spoke only of truth, of love, of the coming kingdom.'", "یشوع گفت: «اما علیه امپراتور سخن نگفتم. تنها از حقیقت گفتم، از عشق، از پادشاهی آینده.»"),
            StoryParagraph("Pilate looked at him, and he knew that the prisoner was innocent; he knew that the accusations were false; he knew that he was about to commit an injustice.", "پیلاطس نگاهش کرد و می‌دانست زندانی بی‌گناه است؛ می‌دانست اتهامات دروغ است؛ می‌دانست در شرف ارتکاب بی‌عدالتی است."),
            StoryParagraph("But he also knew that he had no choice; he was a procurator, a servant of Rome; his duty was to keep the peace, at any cost.", "اما همچنین می‌دانست چاره‌ای ندارد؛ والی بود، خدمتگزار روم؛ وظیفه‌اش حفظ صلح بود، هر چه هزینه داشت."),
            StoryParagraph("'I wash my hands of this,' he said, and he called for water, and he washed his hands before the crowd.", "گفت: «دست‌هایم را از این شست‌وشو می‌دهم.» و آب خواست و دستانش را در برابر جمعیت شست."),
            StoryParagraph("'You will be executed,' he said to Yeshua. 'Not because you are guilty, but because the peace demands it.'", "به یشوع گفت: «اعدام می‌شوی. نه چون گناهکاری، بلکه چون صلح می‌طلبد.»"),
            StoryParagraph("Yeshua looked at him, and there was no anger in his eyes, no hatred, no fear.", "یشوع نگاهش کرد و خشمی در چشمانش نبود، نه نفرتی، نه ترسی."),
            StoryParagraph("'I forgive you,' he said. 'And one day, you will forgive yourself.'", "گفت: «می‌بخشمت. و روزی، خودت را خواهی بخشید.»"),
            StoryParagraph("They led him away, to Golgotha, to the cross; and Pilate stood on the colonnade, and watched him go, and felt as if something in him had died.", "بردندش، به جلجتا، به صلیب؛ و پیلاطس روی ایوان ستون‌دار ایستاد و تماشا کرد که می‌رود و حس کرد گویی چیزی در او مرده."),
            StoryParagraph("He had condemned an innocent man to death; he had washed his hands; he had saved the peace; he had lost his soul.", "او مردی بی‌گناه را به مرگ محکوم کرده بود؛ دست‌هایش را شسته بود؛ صلح را نجات داده بود؛ روحش را از دست داده بود."),
            StoryParagraph("And for two thousand years, he would be haunted by that morning, by that decision, by that man.", "و برای دو هزار سال، توسط آن صبح تسخیر می‌شد، توسط آن تصمیم، توسط آن مرد."),
            StoryParagraph("For two thousand years, he would sit alone on his rocky throne, dreaming of the moon, dreaming of the man he had killed.", "برای دو هزار سال، تنهای روی تخت سنگی‌اش می‌نشست، در خواب ماه را می‌دید، مردی را که کشته بود."),
            StoryParagraph("And in his dreams, he would hear Yeshua's voice: 'I forgive you. And one day, you will forgive yourself.'", "و در خواب‌هایش، صدای یشوع را می‌شنید: «می‌بخشمت. و روزی، خودت را خواهی بخشید.»"),
            StoryParagraph("But Pilate could not forgive himself; he could not forgive what he had done; he could not forgive the choice he had made.", "اما پیلاطس نمی‌توانست خودش را ببخشد؛ نمی‌توانست آنچه کرده بود را ببخشد؛ نمی‌توانست انتخابی که کرده بود را ببخشد."),
            StoryParagraph("And so he sat, for two thousand years, alone with his guilt, alone with his regret, alone with his impossible wish.", "و اینگونه نشست، دو هزار سال، تنها با گناهش، تنها با پشیمانی‌اش، تنها با آرزوی ناممکنش."),
            StoryParagraph("Until at last, at the end of the story, he was granted release, and he walked with Yeshua on a moonlit path, and he was finally at peace.", "تا اینکه سرانجام، در پایان داستان، آزادی به او عطا شد و با یشوع روی راهی زیر نور ماه قدم زد و بالاخره در آرامش بود."),
            StoryParagraph("But that was the end; for now, there was only the morning in Jerusalem, and the cross on Golgotha, and the man Pilate had killed.", "اما آن پایان بود؛ برای اکنون، تنها صبح اورشلیم بود و صلیب روی جلجتا و مردی که پیلاطس کشته بود."),
            StoryParagraph("And the story of Yeshua, told by Woland to two writers on a bench in Moscow, in the hot spring of 1930.", "و داستان یشوع، که ولاند برای دو نویسنده روی نیمکتی در مسکو تعریف کرده بود، در بهار گرم ۱۹۳۰.")
        )
    )

    // ─────────── فصل ۳: استاد ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "The Master", titlePersian = "استاد",
        paragraphs = listOf(
            StoryParagraph("That night, Ivan Bezdomny was taken to a mental hospital, on the outskirts of Moscow, where he was diagnosed with schizophrenia.", "آن شب، ایوان بزدومنی به بیمارستان روانی‌ای در حاشیه مسکو برده شد، جایی که اسکیزوفرنی تشخیصش دادند."),
            StoryParagraph("He did not feel mad; he felt, on the contrary, that he had never been more sane; but he could not explain what he had seen, and so he was put in a ward.", "احساس دیوانگی نمی‌کرد؛ برعکس، حس می‌کرد هرگز عاقل‌تر نبوده؛ اما نمی‌توانست آنچه دیده بود را توضیح دهد و بنابراین به بخشی فرستاده شد."),
            StoryParagraph("There, in the ward, he met a man who introduced himself simply as 'the Master.'", "آنجا، در بخش، با مردی آشنا شد که خودش را به‌سادگی «استاد» معرفی کرد."),
            StoryParagraph("The Master was a man of about forty, with dark hair going grey at the temples, and with a face that had known great happiness and greater sorrow.", "استاد مردی حدوداً چهل ساله بود، با موهای تیره که در شقیقه‌ها خاکستری می‌شد و با چهره‌ای که شادی فراوان و اندوه بیشتر را شناخته بود."),
            StoryParagraph("He was calm, and kind, and sad; he spoke in a low voice, and his words carried weight.", "آرام بود و مهربان و غمگین؛ با صدای پایین صحبت می‌کرد و کلماتش وزن داشتند."),
            StoryParagraph("'You are here because of Woland,' he said, and Ivan was startled.", "گفت: «تو به خاطر ولاند اینجایی.» و ایوان جا خورد."),
            StoryParagraph("'How do you know about Woland?' Ivan asked.", "ایوان پرسید: «از کجا ولاند را می‌شناسی؟»"),
            StoryParagraph("'I know many things,' the Master said, 'or rather, I knew many things. Once. Before I stopped knowing.'", "استاد گفت: «چیزهای بسیاری می‌دانم، یا بهتر، چیزهای بسیاری می‌دانستم. یک بار. قبل از اینکه دست از دانستن بکشم.»"),
            StoryParagraph("He told Ivan his story; he told him about his novel; he told him about Margarita.", "داستانش را برای ایوان گفت؛ از رمانش گفت؛ از مارگاریتا گفت."),
            StoryParagraph("His name, he said, was not important; he had once been a historian, a scholar, a man of learning; but he had given all that up to write a novel.", "گفت اسمش مهم نیست؛ روزی مورخ بوده، دانشمند، مردی اهل دانش؛ اما همه‌اش را رها کرده بود تا رمانی بنویسد."),
            StoryParagraph("The novel was about Pontius Pilate; it was about the trial of Yeshua; it was about the moment when a man chooses between his conscience and his comfort.", "رمان درباره پونتیوس پیلاطس بود؛ درباره محاکمه یشوع بود؛ درباره لحظه‌ای بود که انسانی میان وجدانش و راحتش یکی را برمی‌گزیند."),
            StoryParagraph("'I wrote it in a small basement apartment,' the Master said, 'a place I rented for almost nothing. There was a window, and through the window I could see a lilac bush.'", "استاد گفت: «در آپارتمانی کوچک در زیرزمین نوشتمش، جایی که تقریباً مجانی اجاره کرده بودم. پنجره‌ای بود و از پنجره می‌توانستم بوته یاسی را ببینم.»"),
            StoryParagraph("'It was spring when I began,' he continued. 'And it was spring when I finished. And in between, I lived more fully than I have ever lived before or since.'", "ادامه داد: «وقتی شروع کردم بهار بود. و وقتی تمام کردم هم بهار بود. و در این بین، کامل‌تر از هر وقت دیگری، قبل یا بعد، زندگی کردم.»"),
            StoryParagraph("'I did not eat much, and I did not sleep much, and I did not see anyone; I just wrote, and the writing was everything.'", "«زیاد نمی‌خوردم و زیاد نمی‌خوابیدم و کسی را نمی‌دیدم؛ فقط می‌نوشتم و نوشتن همه چیز بود.»"),
            StoryParagraph("'And then, one day, I met Margarita.'", "«و بعد، یک روز، مارگاریتا را ملاقات کردم.»"),
            StoryParagraph("Margarita, he said, was the most beautiful woman he had ever seen; but more than that, she was the most alive.", "گفت مارگاریتا زیباترین زنی بود که هرگز دیده بود؛ اما بیش از آن، زنده‌ترین."),
            StoryParagraph("She was married to a wealthy man, a famous engineer, a man of importance; she lived in a mansion, wore fine clothes, went to fine parties.", "با مردی ثروتمند ازدواج کرده بود، مهندسی مشهور، مردی با اهمیت؛ در عمارتی زندگی می‌کرد، لباس‌های نفیس می‌پوشید، به مهمانی‌های فاخر می‌رفت."),
            StoryParagraph("But she was not happy; she had never been happy; she had married for security, and she had learned that security is not the same as happiness.", "اما خوشحال نبود؛ هرگز خوشحال نبوده بود؛ برای امنیت ازدواج کرده بود و آموخته بود امنیت همان خوشبختی نیست."),
            StoryParagraph("When she met the Master, she knew, in an instant, that she had found what she had been seeking; and she gave herself to him, completely, without reservation.", "وقتی استاد را ملاقات کرد، در یک لحظه دانست که آنچه در جستجویش بود را یافته؛ و خودش را به او داد، کاملاً، بدون قید و شرط."),
            StoryParagraph("'She was my first reader,' the Master said, 'and my only reader, and my best reader. She understood the novel better than I did.'", "استاد گفت: «او نخستین خواننده‌ام بود و تنها خواننده‌ام و بهترین خواننده‌ام. رمان را بهتر از خودم می‌فهمید.»"),
            StoryParagraph("'She said the novel was true; she said it was important; she said it must be published.'", "«می‌گفت رمان راستین است؛ می‌گفت مهم است؛ می‌گفت باید منتشر شود.»"),
            StoryParagraph("But the novel was not published; it was rejected by every publisher in Moscow; and then, worse, it was attacked.", "اما رمان منتشر نشد؛ توسط هر ناشری در مسکو رد شد؛ و بعد، بدتر، مورد حمله قرار گرفت."),
            StoryParagraph("Critics wrote articles about it, mocking it, condemning it, calling it anti-Soviet, anti-revolutionary, anti-proletarian.", "منتقدان مقاله‌هایی درباره‌اش نوشتند، مسخره‌اش کردند، محکومش کردند، ضدشوروی خواندندش، ضد انقلابی، ضد پرولتری."),
            StoryParagraph("'I was destroyed by those articles,' the Master said, 'not as a writer, but as a man. I lost my faith in myself; I lost my faith in my work; I lost my faith in everything.'", "استاد گفت: «توسط آن مقاله‌ها نابود شدم؛ نه به‌عنوان نویسنده، بلکه به‌عنوان انسان. ایمانم به خودم را از دست دادم؛ ایمانم به کارم را؛ ایمانم به همه چیز را.»"),
            StoryParagraph("And so, one night, in a moment of despair, he had burned his manuscript.", "و اینگونه، یک شب، در لحظه‌ای از ناامیدی، دست‌نوشته‌اش را سوزانده بود."),
            StoryParagraph("'I threw it into the stove,' he said, 'page by page, chapter by chapter. And I watched it burn, and I felt nothing, and then I felt everything.'", "گفت: «در بخاری انداختمش، صفحه به صفحه، فصل به فصل. و تماشا کردم که می‌سوزد و هیچ حس نکردم و بعد همه چیز حس کردم.»"),
            StoryParagraph("Margarita had saved a few pages, without his knowing; she had hidden them, kept them, protected them.", "مارگاریتا چند صفحه را بدون اطلاعش نجات داده بود؛ پنهانشان کرده بود، نگهشان داشته بود، محافظتشان کرده بود."),
            StoryParagraph("'She believed in the novel,' the Master said, 'even when I did not. She believed in me, even when I did not.'", "استاد گفت: «او به رمان باور داشت، حتی وقتی من نداشتم. به من باور داشت، حتی وقتی من نداشتم.»"),
            StoryParagraph("But then the Master had been arrested; he had been taken away, in the middle of the night, by men who did not tell him why.", "اما بعد استاد دستگیر شده بود؛ برده شده بود، در نیمه‌شب، توسط مردانی که نگفتند چرا."),
            StoryParagraph("He had been questioned, and threatened, and tortured, though not with physical violence.", "بازپرسی شده بود و تهدید و شکنجه، هرچند نه با خشونت فیزیکی."),
            StoryParagraph("'They broke me,' he said, 'with words, with silence, with the endless waiting. And when they let me go, I was no longer myself.'", "گفت: «شکستنم، با کلمات، با سکوت، با انتظار بی‌پایان. و وقتی رهایم کردند، دیگر خودم نبودم.»"),
            StoryParagraph("He had come to the mental hospital of his own will; he had asked to be admitted; he had wanted, he said, to be somewhere quiet, somewhere he could disappear.", "به خواست خودش به بیمارستان روانی آمده بود؛ خواسته بود پذیرفته شود؛ گفته بود می‌خواهد جایی آرام باشد، جایی که بتواند ناپدید شود."),
            StoryParagraph("'I do not want to write anymore,' he said. 'I do not want to think anymore. I do not want to feel anymore. I want to be nothing.'", "گفت: «دیگر نمی‌خواهم بنویسم. دیگر نمی‌خواهم فکر کنم. دیگر نمی‌خواهم حس کنم. می‌خواهم هیچ باشم.»"),
            StoryParagraph("And yet, he said, he still thought of Margarita, every day, every hour, every moment.", "و با این حال، گفت، هنوز به مارگاریتا فکر می‌کرد، هر روز، هر ساعت، هر لحظه."),
            StoryParagraph("'She is the only thing I have left,' he said. 'She is the only thing I still believe in.'", "گفت: «او تنها چیزی است که برایم مانده. او تنها چیزی است که هنوز به آن باورم.»"),
            StoryParagraph("Ivan listened, and he did not know what to say; he had never heard such a story, such sorrow, such love.", "ایوان گوش داد و نمی‌دانست چه بگوید؛ هرگز چنین داستانی نشنیده بود، چنین اندوهی، چنین عشقی."),
            StoryParagraph("'You will meet her,' the Master said. 'She will come for me. And perhaps, she will come for you too.'", "استاد گفت: «او را ملاقات خواهی کرد. برای من می‌آید. و شاید، برای تو هم بیاید.»"),
            StoryParagraph("'How do you know?' Ivan asked.", "ایوان پرسید: «از کجا می‌دانی؟»"),
            StoryParagraph("'Because she loves me,' the Master said. 'Because love like that does not end. Because love like that cannot end.'", "استاد گفت: «چون دوستم دارد. چون چنین عشقی تمام نمی‌شود. چون چنین عشقی نمی‌تواند تمام شود.»"),
            StoryParagraph("And so Ivan sat with the Master, in the quiet ward, and they talked for hours, about life and death and love and literature.", "و اینگونه ایوان با استاد نشست، در بخش ساکت و ساعت‌ها صحبت کردند، درباره زندگی و مرگ و عشق و ادبیات."),
            StoryParagraph("Outside, the spring continued, and the lime trees bloomed, and the world went on as if nothing had happened.", "بیرون، بهار ادامه داشت و درختان آهک شکوفه می‌دادند و جهان ادامه می‌یافت گویی هیچ اتفاقی نیفتاده."),
            StoryParagraph("But inside, in the mental hospital, in the ward, two men had found each other, and in finding each other, they had found a kind of hope.", "اما درون، در بیمارستان روانی، در بخش، دو مرد همدیگر را یافته بودند و در یافتن همدیگر، نوعی امید یافته بودند."),
            StoryParagraph("The Master, who had given up; Ivan, who had lost his mind; both of them, in their brokenness, waiting for something, for someone, for salvation.", "استاد، که دست کشیده بود؛ ایوان، که عقلش را از دست داده بود؛ هر دو، در شکستگی‌شان، منتظر چیزی، کسی، رستگاری."),
            StoryParagraph("And salvation, when it came, would come in the form of a woman named Margarita.", "و رستگاری، چون آمد، در قالب زنی به نام مارگاریتا می‌آمد.")
        )
    )

    // ─────────── فصل ۴: مارگاریتا ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "Margarita", titlePersian = "مارگاریتا",
        paragraphs = listOf(
            StoryParagraph("Margarita Nikolaevna was thirty years old, and she was beautiful, and she was unhappy.", "مارگاریتا نیکولایونا سی ساله بود و زیبا و ناخوشحال."),
            StoryParagraph("She lived in a large apartment in the center of Moscow, with her husband, a famous engineer, a man of importance.", "در آپارتمانی بزرگ در مرکز مسکو زندگی می‌کرد، با شوهرش، مهندسی مشهور، مردی با اهمیت."),
            StoryParagraph("She had everything a woman could want: wealth, status, comfort, security; everything, that is, except the one thing she truly needed.", "هر چیزی که یک زن می‌توانست بخواهد را داشت: ثروت، مقام، راحتی، امنیت؛ هر چیزی، یعنی، جز آن یک چیزی که واقعاً نیاز داشت."),
            StoryParagraph("She needed love; she needed meaning; she needed something worth living for.", "به عشق نیاز داشت؛ به معنا؛ به چیزی که ارزش زیستن داشته باشد."),
            StoryParagraph("She had met the Master two years before, on a street corner, in a crowd, by chance.", "دو سال پیش استاد را ملاقات کرده بود، در گوشه خیابانی، در جمعیتی، تصادفی."),
            StoryParagraph("She had been carrying flowers, yellow flowers, and she had been walking without thinking, and suddenly, there he was.", "گل حمل می‌کرد، گل‌های زرد و بدون فکر راه می‌رفت و ناگهان، او آنجا بود."),
            StoryParagraph("He had looked at her, and she had looked at him, and something passed between them, something that neither could name.", "نگاهش کرده بود و او هم نگاهش کرده بود و چیزی میانشان رد شد، چیزی که هیچ‌کدام نمی‌توانستند نامش را ببرند."),
            StoryParagraph("'Do you like my flowers?' she had asked, and she did not know why she had asked.", "پرسیده بود: «گل‌هایم را دوست داری؟» و نمی‌دانست چرا پرسیده بود."),
            StoryParagraph("'No,' he had said. 'I hate yellow flowers.'", "گفته بود: «نه. از گل‌های زرد متنفرم.»"),
            StoryParagraph("She had laughed, and he had laughed, and they had walked together, and they had talked, and they had fallen in love.", "خندیده بود و او هم خندیده بود و با هم راه رفته بودند و صحبت کرده بودند و عاشق شده بودند."),
            StoryParagraph("It had been sudden, and total, and irreversible; it had been, Margarita thought, like a disease, like a madness, like a miracle.", "ناگهانی بود و کامل و برگشت‌ناپذیر؛ مارگاریتا فکر می‌کرد، مثل بیماری بود، مثل جنون، مثل معجزه."),
            StoryParagraph("She had left her husband, or tried to; she had left her comfortable life, or tried to; she had given herself, completely, to the Master.", "شوهرش را ترک کرده بود، یا تلاش کرده بود؛ زندگی راحتش را ترک کرده بود، یا تلاش کرده بود؛ خودش را کاملاً به استاد داده بود."),
            StoryParagraph("But the Master had been destroyed; the critics had destroyed him; the world had destroyed him.", "اما استاد نابود شده بود؛ منتقدان نابودش کرده بودند؛ جهان نابودش کرده بود."),
            StoryParagraph("And Margarita had been left alone, with her love, with her memory, with her impossible hope.", "و مارگاریتا تنها مانده بود، با عشقش، با خاطره‌اش، با امید ناممکنش."),
            StoryParagraph("Every night, she prayed; every night, she begged; every night, she asked for the Master to be returned to her.", "هر شب دعا می‌کرد؛ هر شب التماس می‌کرد؛ هر شب می‌خواست استاد به او بازگردانده شود."),
            StoryParagraph("But no answer came; the heavens were silent; the world went on; and Margarita was left with her sorrow.", "اما پاسخی نمی‌آمد؛ آسمان‌ها ساکت بودند؛ جهان ادامه می‌یافت؛ و مارگاریتا با اندوهش تنها ماند."),
            StoryParagraph("And then, one spring afternoon, in her apartment, alone, thinking of the Master, she received a visitor.", "و بعد، یک بعدازظهر بهاری، در آپارتمانش، تنها، در فکر استاد، مهمانی دریافت کرد."),
            StoryParagraph("He was a small man, with a checkered jacket and a bowler hat, and a face that was somehow both comic and sinister.", "مردی کوچک بود، با کتی شطرنجی و کلاه ملوانی و چهره‌ای که به شکلی هم خنده‌دار و هم شوم بود."),
            StoryParagraph("'Good afternoon,' he said. 'I am Azazello. I have come on behalf of a certain gentleman, a foreign gentleman, who would like to make your acquaintance.'", "گفت: «بعدازظهر بخیر. من آزازلو هستم. از طرف جنتلمنی خاص آمده‌ام، جنتلمنی خارجی، که مایل است با شما آشنا شود.»"),
            StoryParagraph("'What gentleman?' Margarita asked.", "مارگاریتا پرسید: «چه جنتلمنی؟»"),
            StoryParagraph("'A gentleman of great importance,' Azazello said. 'A gentleman who can grant you any wish, any wish at all.'", "آزازلو گفت: «جنتلمنی با اهمیت فراوان. جنتلمنی که می‌تواند هر آرزویی، هر آرزویی را به شما عطا کند.»"),
            StoryParagraph("'Any wish?' Margarita asked, and her heart began to beat faster.", "مارگاریتا پرسید: «هر آرزویی؟» و قلبش شروع کرد به تندتر تپیدن."),
            StoryParagraph("'Any wish,' Azazello said. 'Including — and I think this is what you really want — the return of a certain Master, who is now, shall we say, unavailable.'", "آزازلو گفت: «هر آرزویی. از جمله — و فکر می‌کنم این چیزی است که واقعاً می‌خواهید — بازگشت استاد خاصی، که اکنون، بگوییم، در دسترس نیست.»"),
            StoryParagraph("Margarita was stunned; she did not know who this man was, or how he knew about the Master, or what he wanted.", "مارگاریتا مبهوت شد؛ نمی‌دانست این مرد کیست، یا از کجا استاد را می‌شناسد، یا چه می‌خواهد."),
            StoryParagraph("'What is the price?' she asked, and her voice was steady.", "پرسید: «قیمتش چیست؟» و صدایش ثابت بود."),
            StoryParagraph("'The price,' Azazello said, 'is that you must do us a small service. You must be the hostess at a certain ball. A ball given by my master, tonight.'", "آزازلو گفت: «قیمت این است که باید خدمت کوچکی به ما بکنید. باید میزبان بالماسکه‌ای باشید. بالماسکه‌ای که ارباب من امشب می‌دهد.»"),
            StoryParagraph("'What kind of ball?' Margarita asked.", "مارگاریتا پرسید: «چه نوع بالماسکه‌ای؟»"),
            StoryParagraph("'The ball of the spring full moon,' Azazello said. 'The ball of Satan. But do not be alarmed; the guests are all very distinguished, and the company is excellent.'", "آزازلو گفت: «بالماسکه ماه کامل بهار. بالماسکه شیطان. اما نگران نباشید؛ مهمانان همه بسیار برجسته‌اند و رفقا عالی‌اند.»"),
            StoryParagraph("Margarita understood, or thought she understood, that she was being offered a bargain by forces she did not understand, forces that were beyond good and evil.", "مارگاریتا فهمید، یا فکر کرد فهمید، که معامله‌ای از طرف نیروهایی به او پیشنهاد می‌شود که نمی‌فهمد، نیروهایی فراتر از خوب و بد."),
            StoryParagraph("But she did not care; she did not care about her soul, or her salvation, or anything else; she cared only about the Master.", "اما اهمیتی نمی‌داد؛ به روحش اهمیت نمی‌داد، نه به رستگاری‌اش، نه به چیز دیگری؛ تنها به استاد اهمیت می‌داد."),
            StoryParagraph("'I accept,' she said. 'What must I do?'", "گفت: «می‌پذیرم. چه باید بکنم؟»"),
            StoryParagraph("Azazello handed her a small jar of cream, a golden cream that smelled of flowers and of something else, something ancient and strange.", "آزازلو شیشه کوچکی کرم به او داد، کرمی طلایی که بوی گل می‌داد و بوی چیز دیگری، چیزی کهن و عجیب."),
            StoryParagraph("'Rub this on your body,' he said, 'and you will become invisible. Then, at midnight, come to the address on this card. Everything else will follow.'", "گفت: «این را به بدنت بمال و نامرئی می‌شوی. بعد، در نیمه‌شب، به آدرس روی این کارت بیا. بقیه‌اش خودش می‌آید.»"),
            StoryParagraph("And he was gone, as suddenly as he had come, leaving Margarita alone with the jar, and the card, and her fate.", "و رفت، همان‌قدر ناگهان که آمده بود، مارگاریتا را با شیشه، با کارت و با سرنوشتش تنها گذاشت."),
            StoryParagraph("She did not hesitate; she did not doubt; she did not even think; she simply did what she had been told.", "تردید نکرد؛ شک نکرد؛ حتی فکر نکرد؛ تنها آنچه به او گفته شده بود انجام داد."),
            StoryParagraph("She rubbed the cream on her body, and she felt a strange heat, a strange lightness, a strange power.", "کرم را به بدنش مالید و گرمای عجیبی حس کرد، سبکی عجیب، قدرتی عجیب."),
            StoryParagraph("She looked in the mirror, and she did not see herself; she was invisible; she was free.", "به آینه نگاه کرد و خودش را ندید؛ نامرئی بود؛ آزاد بود."),
            StoryParagraph("She laughed, and she flew out the window, into the night, into the moonlight, into the impossible.", "خندید و از پنجره بیرون پرید، به شب، به نور ماه، به ناممکن."),
            StoryParagraph("And so Margarita began her transformation, from a woman of sorrow into a witch of power, from a prisoner of fate into a mistress of fate.", "و اینگونه مارگاریتا دگرگونی‌اش را آغاز کرد، از زنی از اندوه به جادوگری از قدرت، از زندانی سرنوشت به بانوی سرنوشت."),
            StoryParagraph("She flew over Moscow, naked and free, and she laughed, and she screamed, and she felt alive for the first time in years.", "بر فراز مسکو پرواز کرد، برهنه و آزاد، و خندید و فریاد زد و برای نخستین بار در سال‌ها زنده حس کرد."),
            StoryParagraph("She destroyed the apartment of a critic, a man named Latunsky, who had destroyed the Master with his articles; she threw his furniture out the window; she flooded his floors.", "آپارتمان منتقدی را نابود کرد، مردی به نام لاتونسکی، که با مقاله‌هایش استاد را نابود کرده بود؛ مبلمانش را از پنجره بیرون انداخت؛ کف‌هایش را سیلابی کرد."),
            StoryParagraph("It was petty, and it was cruel, and it was cathartic; and it was the first act of justice Margarita had been able to perform.", "کوچک بود و بی‌رحم و تصفیه‌کننده؛ و اولین عمل عدالتی بود که مارگاریتا توانسته بود انجام دهد."),
            StoryParagraph("And then, at midnight, she came to the address on the card, and she entered the world of Woland.", "و بعد، در نیمه‌شب، به آدرس روی کارت آمد و به جهان ولاند وارد شد.")
        )
    )

    // ─────────── فصل ۵: بالماسکه شیطان ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Ball of Satan", titlePersian = "بالماسکه شیطان",
        paragraphs = listOf(
            StoryParagraph("The apartment where Margarita arrived was not, at first glance, unusual.", "آپارتمانی که مارگاریتا به آن رسید، در نگاه اول، غیرعادی نبود."),
            StoryParagraph("It was in a building on Sadovaya Street, on the fourth floor, and it looked exactly like any other Moscow apartment.", "در ساختمانی در خیابان سادووایا بود، در طبقه چهارم و دقیقاً شبیه هر آپارتمان مسکوی دیگری به نظر می‌رسید."),
            StoryParagraph("But when Margarita opened the door, she found herself in a world that no longer obeyed the laws of nature.", "اما وقتی مارگاریتا در را باز کرد، خود را در جهانی یافت که دیگر از قوانین طبیعت پیروی نمی‌کرد."),
            StoryParagraph("The rooms had expanded; the ceilings had risen; the walls had disappeared; she was standing, suddenly, in a vast ballroom.", "اتاق‌ها گسترده شده بودند؛ سقف‌ها بالا رفته بودند؛ دیوارها ناپدید شده بودند؛ ناگهان در تالار بالماسکه‌ای عظیم ایستاده بود."),
            StoryParagraph("The ballroom was full of people — or rather, of beings — dressed in the most extraordinary costumes.", "تالار پر از مردم بود — یا بهتر، از موجودات — با عجیب‌ترین لباس‌ها."),
            StoryParagraph("Some of them were in ball gowns and tuxedos; others were in rags and chains; still others were in costumes from other centuries, other lands, other lives.", "برخی در لباس‌های بالماسکه و کت‌شلوار رسمی بودند؛ دیگران در ژنده‌ها و زنجیرها؛ باز دیگران در لباس‌های قرن‌های دیگر، سرزمین‌های دیگر، زندگی‌های دیگر."),
            StoryParagraph("And at the center of it all, on a high throne, sat Woland, the devil himself, looking at Margarita with his strange, different-colored eyes.", "و در مرکز همه‌اش، روی تختی بلند، ولاند نشسته بود، خود شیطان، با چشمان عجیب و دو رنگش به مارگاریتا نگاه می‌کرد."),
            StoryParagraph("'Welcome, Queen Margot,' he said. 'I have been waiting for you.'", "گفت: «خوش آمدی، ملکه مارگو. منتظرت بوده‌ام.»"),
            StoryParagraph("Margarita was not afraid; she had passed beyond fear; she was, in this moment, something more than human.", "مارگاریتا نترسید؛ از ترس فراتر رفته بود؛ در این لحظه، چیزی بیشتر از انسان بود."),
            StoryParagraph("'I am ready,' she said. 'Tell me what to do.'", "گفت: «آماده‌ام. بگو چه کنم.»"),
            StoryParagraph("'You must be the hostess,' Woland said. 'You must greet the guests. You must smile, and bow, and receive them as if they were your dearest friends.'", "ولاند گفت: «باید میزبان باشی. باید مهمانان را خوش‌آمد بگویی. باید لبخند بزنی و تعظیم کنی و مثل عزیزترین دوستانت پذیرایشان باشی.»"),
            StoryParagraph("'And the guests?' Margarita asked.", "مارگاریتا پرسید: «و مهمانان؟»"),
            StoryParagraph("'The guests,' Woland said, 'are the dead. They are murderers and victims, saints and sinners, lovers and betrayers. They are all the souls who have ever lived, and who have ever died.'", "ولاند گفت: «مهمانان مردگانند. قاتلانند و قربانیان، قدیسان و گناهکاران، عاشقان و خائنان. همه روح‌هایی هستند که هرگز زیسته‌اند و هرگز مرده‌اند.»"),
            StoryParagraph("Margarita nodded; she understood, or thought she understood; she was ready.", "مارگاریتا سر تکان داد؛ فهمید، یا فکر کرد فهمید؛ آماده بود."),
            StoryParagraph("And then the ball began.", "و بعد بالماسکه آغاز شد."),
            StoryParagraph("The doors opened, and the guests began to enter, one by one, and then in groups, and then in floods.", "درها باز شدند و مهمانان یکی‌یکی وارد شدند، بعد گروه‌گروه، بعد سیل‌آسا."),
            StoryParagraph("They came in chains, and in jewels; they came bleeding, and they came laughing; they came from every corner of history, from every crime and every virtue.", "با زنجیر آمدند و با جواهر؛ خونین آمدند و خندان؛ از هر گوشه تاریخ آمدند، از هر جنایت و هر فضیلت."),
            StoryParagraph("Margarita greeted them all; she kissed their hands; she smiled at their faces; she welcomed them to the ball.", "مارگاریتا همه را پذیرفت؛ دستانشان را بوسید؛ به چهره‌هایشان لبخند زد؛ به بالماسکه خوش‌آمد گفت."),
            StoryParagraph("She did not judge them; she did not despise them; she simply received them, as they were.", "قضاوتشان نکرد؛ تحقیرشان نکرد؛ تنها پذیرایشان شد، همان‌طور که بودند."),
            StoryParagraph("And in that receiving, in that accepting, in that loving, she found something that she had never found before: a kind of peace, a kind of grace, a kind of redemption.", "و در آن پذیرش، در آن قبول، در آن عشق ورزیدن، چیزی یافت که هرگز قبلاً نیافته بود: نوعی آرامش، نوعی فیض، نوعی رستگاری."),
            StoryParagraph("Hours passed, or perhaps centuries; in that world, time had no meaning.", "ساعت‌ها گذشت، یا شاید قرن‌ها؛ در آن جهان، زمان معنایی نداشت."),
            StoryParagraph("And then, at dawn, the ball ended, and the guests disappeared, and Margarita was left alone with Woland and his retinue.", "و بعد، در سپیده‌دم، بالماسکه تمام شد و مهمانان ناپدید شدند و مارگاریتا با ولاند و اطرافیانش تنها ماند."),
            StoryParagraph("'You have done well,' Woland said. 'You have been a perfect hostess. And now, you may ask for your reward.'", "ولاند گفت: «خوب انجام دادی. میزبان کاملی بوده‌ای. و حالا، می‌توانی پاداشت را بخواهی.»"),
            StoryParagraph("Margarita did not hesitate; she had known what she would ask from the beginning.", "مارگاریتا تردید نکرد؛ از آغاز می‌دانست چه می‌خواهد."),
            StoryParagraph("'I want the Master,' she said. 'I want him returned to me. I want him alive, and well, and with me.'", "گفت: «استاد را می‌خواهم. می‌خواهم به من بازگردانده شود. می‌خواهم زنده باشد و خوب و با من.»"),
            StoryParagraph("Woland looked at her, and for a moment, there was something in his eyes that might have been admiration, or might have been pity.", "ولاند نگاهش کرد و لحظه‌ای چیزی در چشمانش بود که می‌توانست تحسین باشد، یا ترحم."),
            StoryParagraph("'You are a remarkable woman,' he said. 'You have passed through hell, and you have asked not for your own salvation, but for another's.'", "گفت: «زنی قابل توجهی هستی. از جهنم گذشتی و نه رستگاری خودت را خواستی، بلکه رستگاری دیگری را.»"),
            StoryParagraph("'He is my salvation,' Margarita said. 'Without him, there is nothing to save.'", "مارگاریتا گفت: «او رستگاری من است. بدون او، چیزی برای نجات نیست.»"),
            StoryParagraph("And so Woland granted her wish; and the Master was brought to her, out of the mental hospital, out of his despair, out of the darkness.", "و اینگونه ولاند آرزویش را برآورده کرد؛ و استاد به او آورده شد، از بیمارستان روانی، از ناامیدی‌اش، از تاریکی."),
            StoryParagraph("He was confused, and afraid, and disoriented; but when he saw Margarita, when he saw her face, when he felt her arms around him, he began to weep.", "گیج بود و ترسیده و سرگشته؛ اما وقتی مارگاریتا را دید، وقتی چهره‌اش را دید، وقتی بازوهایش را دور خودش حس کرد، شروع به گریستن کرد."),
            StoryParagraph("'You came for me,' he said. 'You came for me.'", "گفت: «برای من آمدی. برای من آمدی.»"),
            StoryParagraph("'Of course I came,' she said. 'How could I not come? How could I ever not come?'", "گفت: «البته که آمدم. چطور ممکن بود نیایم؟ چطور ممکن بود هرگز نیایم؟»"),
            StoryParagraph("And they held each other, in the strange world of Woland, in the aftermath of the ball, in the dawn of a new day.", "و همدیگر را در آغوش گرفتند، در جهان عجیب ولاند، در پس‌آیند بالماسکه، در سپیده‌دم روزی نو."),
            StoryParagraph("They did not know what would happen next; they did not know what Woland would do with them; they did not know what fate awaited them.", "نمی‌دانستند بعد چه می‌شود؛ نمی‌دانستند ولاند با آن‌ها چه می‌کند؛ نمی‌دانستند چه سرنوشتی در انتظارشان است."),
            StoryParagraph("But they were together, and that was enough; they were together, and that was everything.", "اما با هم بودند و همین کافی بود؛ با هم بودند و همین همه چیز بود."),
            StoryParagraph("And so, in the midst of darkness, in the heart of the devil's ball, love had found a way.", "و اینگونه، در میانه تاریکی، در قلب بالماسکه شیطان، عشق راهی یافته بود.")
        )
    )

    // ─────────── فصل ۶: رهایی ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "Liberation", titlePersian = "رهایی",
        paragraphs = listOf(
            StoryParagraph("The Master and Margarita were taken by Woland and his retinue to a place outside of time, outside of space, outside of everything they had known.", "استاد و مارگاریتا توسط ولاند و اطرافیانش به جایی برده شدند بیرون از زمان، بیرون از مکان، بیرون از هر چیزی که می‌شناختند."),
            StoryParagraph("It was not heaven; it was not hell; it was something else entirely, something that had no name.", "نه بهشت بود؛ نه جهنم؛ چیز کاملاً دیگری بود، چیزی که نامی نداشت."),
            StoryParagraph("They were standing on a road, a moonlit road, in a landscape of impossible beauty.", "روی جاده‌ای ایستاده بودند، جاده‌ای زیر نور ماه، در منظره‌ای با زیبایی ناممکن."),
            StoryParagraph("Behind them, the city of Moscow had disappeared; before them, there was only the road, and the moon, and the silence.", "پشت سرشان، شهر مسکو ناپدید شده بود؛ پیش رویشان، تنها جاده بود و ماه و سکوت."),
            StoryParagraph("'Where are we?' the Master asked.", "استاد پرسید: «کجاییم؟»"),
            StoryParagraph("'Nowhere,' Woland said. 'And everywhere. This is the place between places, the time between times. This is where souls come to rest.'", "ولاند گفت: «هیچ‌جا. و همه‌جا. این جایی است میان جاها، زمانی میان زمان‌ها. اینجاست که روح‌ها برای آسودن می‌آیند.»"),
            StoryParagraph("'Are we dead?' Margarita asked.", "مارگاریتا پرسید: «مرده‌ایم؟»"),
            StoryParagraph("'No,' Woland said. 'You are more alive than you have ever been. You have passed through death, and you have come out the other side. You are free.'", "ولاند گفت: «نه. زنده‌تر از هر وقت دیگری هستید. از مرگ گذشته‌اید و از آنسو بیرون آمده‌اید. آزادید.»"),
            StoryParagraph("And then Woland told them what he had decided; he told them what he had been instructed to do.", "و بعد ولاند به آن‌ها گفت چه تصمیمی گرفته؛ گفت چه به او دستور داده شده بود."),
            StoryParagraph("'You cannot have light,' he said. 'That is not for you. You have not earned it; you have not suffered enough; you have not loved enough.'", "گفت: «نمی‌توانید نور داشته باشید. آن برای شما نیست. آن را به دست نیاورده‌اید؛ به اندازه کافی رنج نکشیده‌اید؛ به اندازه کافی عشق نورزیده‌اید.»"),
            StoryParagraph("'Then what can we have?' the Master asked.", "استاد پرسید: «پس چه می‌توانیم داشته باشیم؟»"),
            StoryParagraph("'You can have peace,' Woland said. 'Not the peace of heaven, but the peace of a quiet life. A house, a garden, the sound of rain on the roof. No fear, no guilt, no regret. Just peace.'", "ولاند گفت: «می‌توانید آرامش داشته باشید. نه آرامش بهشت، بلکه آرامش زندگی‌ای ساکت. خانه‌ای، باغی، صدای باران روی سقف. نه ترس، نه گناه، نه پشیمانی. تنها آرامش.»"),
            StoryParagraph("'And my novel?' the Master asked. 'Will anyone read it?'", "استاد پرسید: «و رمانم؟ کسی می‌خواندش؟»"),
            StoryParagraph("'Your novel will be read,' Woland said. 'In another time, in another country, by people who will understand it. But you will not know; you will be at peace; you will be beyond fame and beyond obscurity.'", "ولاند گفت: «رمانت خوانده خواهد شد. در زمانی دیگر، در کشوری دیگر، توسط افرادی که می‌فهمندش. اما تو نخواهی دانست؛ در آرامش خواهی بود؛ فراتر از شهرت و فراتر از گمنامی.»"),
            StoryParagraph("'And my students?' the Master said. 'What will become of those I left behind?'", "استاد گفت: «و شاگردانم؟ بر سر آنان که رها کردم چه می‌آید؟»"),
            StoryParagraph("'Ivan Bezdomny,' Woland said, 'will become a professor of history. He will never write poetry again. But every year, at the spring full moon, he will have a strange dream. He will dream of you, and of Margarita, and of Pilate, and of Yeshua. And he will remember.'", "ولاند گفت: «ایوان بزدومنی استاد تاریخ می‌شود. دیگر هرگز شعر نخواهد نوشت. اما هر سال، در ماه کامل بهار، خواب عجیبی خواهد دید. خواب تو را خواهد دید و مارگاریتا و پیلاطس و یشوع. و به یاد خواهد آورد.»"),
            StoryParagraph("'And Berlioz?' the Master asked.", "استاد پرسید: «و برلیوز؟»"),
            StoryParagraph("'Berlioz is dead,' Woland said. 'His head is gone. His soul is gone. Nothing remains. He did not believe in anything, and so nothing remains of him.'", "ولاند گفت: «برلیوز مرده است. سرش رفته. روحش رفته. هیچ چیز نمی‌ماند. به هیچ چیز باور نداشت و بنابراین هیچ چیز از او نمی‌ماند.»"),
            StoryParagraph("'And Pontius Pilate?' the Master asked. 'Will he ever be free?'", "استاد پرسید: «و پونتیوس پیلاطس؟ هرگز آزاد می‌شود؟»"),
            StoryParagraph("'That,' Woland said, 'is up to you. You wrote his story. You gave him his suffering. And you, and only you, can give him his release.'", "ولاند گفت: «این به تو بستگی دارد. تو داستانش را نوشتی. تو رنجش را دادی. و تو، و تنها تو، می‌توانی آزادی‌اش را بدهی.»"),
            StoryParagraph("The Master was silent for a long time, and then he spoke.", "استاد مدت طولانی ساکت بود و بعد صحبت کرد."),
            StoryParagraph("'He has suffered enough,' he said. 'He has been alone long enough. Let him be free.'", "گفت: «به اندازه کافی رنج کشیده. به اندازه کافی تنها بوده. بگذار آزاد باشد.»"),
            StoryParagraph("And at that moment, in a place far away, on a rocky throne, an old man looked up, and saw the moonlight, and understood that he had been forgiven.", "و در آن لحظه، در جایی دور، روی تختی سنگی، پیرمردی سر بلند کرد و نور ماه را دید و فهمید که بخشیده شده است."),
            StoryParagraph("Pilate rose from his throne, and he walked out into the night, and there, on a moonlit path, he met Yeshua.", "پیلاطس از تختش بلند شد و به شب بیرون رفت و آنجا، روی راهی زیر نور ماه، یشوع را ملاقات کرد."),
            StoryParagraph("'You are here,' Pilate said.", "پیلاطس گفت: «اینجایی.»"),
            StoryParagraph("'I have always been here,' Yeshua said. 'I have always been waiting for you.'", "یشوع گفت: «همیشه اینجا بوده‌ام. همیشه منتظرت بوده‌ام.»"),
            StoryParagraph("'I am sorry,' Pilate said. 'I am sorry for what I did. I am sorry for what I was.'", "پیلاطس گفت: «متأسفم. برای آنچه کردم متأسفم. برای آنچه بودم متأسفم.»"),
            StoryParagraph("'I know,' Yeshua said. 'I have always known. And I have always forgiven you.'", "یشوع گفت: «می‌دانم. همیشه می‌دانستم. و همیشه بخشیده‌ام.»"),
            StoryParagraph("And the two men, the judge and the judged, the killer and the killed, walked together into the light, and they were at peace.", "و آن دو مرد، قاضی و قضاوت‌شده، قاتل و کشته، با هم به نور رفتند و در آرامش بودند."),
            StoryParagraph("'And now,' Woland said, turning to the Master and Margarita, 'you will go to your place. You will go to your house. You will go to your peace.'", "و ولاند رو به استاد و مارگاریتا کرد: «و حالا، به جای خودتان می‌روید. به خانه‌تان. به آرامشتان.»"),
            StoryParagraph("'Will we be together?' Margarita asked.", "مارگاریتا پرسید: «با هم خواهیم بود؟»"),
            StoryParagraph("'You will be together,' Woland said. 'You will always be together. That is the gift I give you. That is the reward for your love.'", "ولاند گفت: «با هم خواهید بود. همیشه با هم خواهید بود. این هدیه‌ای است که به شما می‌دهم. این پاداش عشق شماست.»"),
            StoryParagraph("And so the Master and Margarita walked down the moonlit road, hand in hand, toward a small house, with a garden, and a lilac bush, and a window.", "و اینگونه استاد و مارگاریتا در جاده زیر نور ماه قدم زدند، دست در دست، به سمت خانه‌ای کوچک، با باغی و بوته یاسی و پنجره‌ای."),
            StoryParagraph("It was the same house they had once shared, in Moscow, in another life; but now it was somewhere else, somewhere beyond." , "همان خانه‌ای بود که روزی در مسکو، در زندگی‌ای دیگر، با هم قسمت کرده بودند؛ اما حالا جای دیگری بود، جایی فراتر."),
            StoryParagraph("They entered the house, and they lit a fire, and they sat by the window, and they watched the moon.", "وارد خانه شدند و آتش روشن کردند و کنار پنجره نشستند و ماه را تماشا کردند."),
            StoryParagraph("'Will you write again?' Margarita asked.", "مارگاریتا پرسید: «دوباره می‌نویسی؟»"),
            StoryParagraph("'Perhaps,' the Master said. 'But it does not matter. What matters is that we are here, that we are together, that we are at peace.'", "استاد گفت: «شاید. اما مهم نیست. آنچه مهم است این است که اینجاییم، با هم، در آرامش.»"),
            StoryParagraph("'And your novel?' she asked. 'Will it ever be published?'", "پرسید: «و رمانت؟ هرگز منتشر می‌شود؟»"),
            StoryParagraph("'It will be published,' he said. 'Someday. Somewhere. But I will not know. And that is fine. It is better, even. The work is done; the work is out in the world; the rest is not my concern.'", "گفت: «منتشر می‌شود. روزی. جایی. اما نمی‌دانم. و همین خوب است. حتی بهتر است. کار تمام شده؛ کار در جهان است؛ باقی نگرانی من نیست.»"),
            StoryParagraph("And so they sat, in the quiet house, in the moonlit night, and they talked, and they laughed, and they loved.", "و اینگونه نشستند، در خانه ساکت، در شب زیر نور ماه و صحبت کردند و خندیدند و عشق ورزیدند."),
            StoryParagraph("They had passed through the fire, and they had come out the other side; they had faced the devil, and they had been found worthy; they had loved each other, and they had been rewarded.", "از آتش گذشته بودند و از آنسو بیرون آمده بودند؛ با شیطان روبرو شده بودند و سزاوار شناخته شده بودند؛ همدیگر را دوست داشته بودند و پاداش یافته بودند."),
            StoryParagraph("Not with light, not with salvation, not with the joy of heaven; but with peace, with quiet, with the simple happiness of being together.", "نه با نور، نه با رستگاری، نه با شادی بهشت؛ بلکه با آرامش، با سکوت، با خوشبختی ساده با هم بودن."),
            StoryParagraph("And that, Woland had said, was enough; and that, the Master and Margarita discovered, was more than enough.", "و آن، ولاند گفته بود، کافی بود؛ و آن، استاد و مارگاریتا کشف کردند، بیش از کافی بود."),
            StoryParagraph("It was everything.", "همه چیز بود."),
            StoryParagraph("And so the story ended, in a small house, on a moonlit road, in a place beyond places and a time beyond times.", "و اینگونه داستان پایان یافت، در خانه‌ای کوچک، روی راهی زیر نور ماه، در جایی فراتر از جاها و زمانی فراتر از زمان‌ها."),
            StoryParagraph("The Master had found his peace; Margarita had found her love; and the world, the real world, went on as it always had.", "استاد آرامشش را یافته بود؛ مارگاریتا عشقش؛ و جهان، جهان واقعی، همانطور که همیشه بود ادامه می‌یافت.")
        )
    )

    // ─────────── فصل ۷: معنا ───────────
    private fun chapter7() = StoryChapter(
        number = 7, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("The Master and Margarita is the last and greatest novel of Mikhail Bulgakov, and one of the most extraordinary works of the twentieth century.", "استاد و مارگاریتا آخرین و بزرگ‌ترین رمان میخائیل بولگاکف است و یکی از فوق‌العاده‌ترین آثار قرن بیستم."),
            StoryParagraph("Bulgakov wrote it over twelve years, from 1928 to 1940, revising it constantly, burning drafts, starting over, never fully satisfied.", "بولگاکف دوازده سال آن را نوشت، از ۱۹۲۸ تا ۱۹۴۰، مدام بازنویسی می‌کرد، پیش‌نویس‌ها را می‌سوزاند، از نو شروع می‌کرد، هرگز کاملاً راضی نبود."),
            StoryParagraph("He knew he would never see it published in his lifetime; he knew that the Soviet authorities would never permit it; and yet he wrote it anyway, for himself, for the future, for us.", "می‌دانست هرگز انتشارش را در عمرش نمی‌بیند؛ می‌دانست مقامات شوروی هرگز اجازه نمی‌دهند؛ و با این حال به هر حال نوشتش، برای خودش، برای آینده، برای ما."),
            StoryParagraph("He dictated the final revisions to his wife, on his deathbed, blind and in pain, still working, still believing, still refusing to give up.", "آخرین بازنویسی‌ها را در بستر مرگ به همسرش دیکته کرد، نابینا و در درد، هنوز کار می‌کرد، هنوز باور داشت، هنوز از تسلیم شدن امتناع می‌کرد."),
            StoryParagraph("The novel was finally published in 1966, twenty-six years after his death, in a heavily censored version; the uncensored version appeared only in 1973.", "رمان سرانجام در ۱۹۶۶، بیست‌وشش سال پس از مرگش، در نسخه‌ای به‌شدت سانسورشده منتشر شد؛ نسخه سانسورنشده تنها در ۱۹۷۳ ظاهر شد."),
            StoryParagraph("And yet, despite all the delays, despite all the obstacles, despite all the attempts to suppress it, the novel survived, and it has become one of the most beloved books in the world.", "و با این حال، به رغم تمام تأخیرها، به رغم تمام موانع، به رغم تمام تلاش‌ها برای سرکوبش، رمان زنده ماند و به یکی از محبوب‌ترین کتاب‌های جهان تبدیل شده."),
            StoryParagraph("The novel is, on one level, a satire of Soviet Moscow in the 1930s — a city of bureaucrats and censors, of atheism and materialism, of fear and hypocrisy.", "رمان در یک سطح، هجایی است از مسکوی شوروی در دهه ۱۹۳۰ — شهری از بوروکرات‌ها و سانسورچیان، از بی‌خدایی و ماتریالیسم، از ترس و ریاکاری."),
            StoryParagraph("Woland, the devil, arrives in this city with his retinue — a talking black cat named Behemoth, a fanged assassin named Azazello, a witch named Hella, and a strange, silent figure named Koroviev.", "ولاند، شیطان، با اطرافیانش به این شهر می‌آید — گربه سیاه سخنگویی به نام بیهیموت، قاتلی دندان‌نیش‌دار به نام آزازلو، جادوگری به نام هلا و چهره‌ای عجیب و ساکت به نام کوروویف."),
            StoryParagraph("They wreak havoc on the Soviet establishment; they expose the greed and corruption of the officials; they punish the arrogant and reward the humble.", "آن‌ها در نظام شوروی آشوب به پا می‌کنند؛ طمع و فساد مقامات را افشا می‌کنند؛ متکبران را مجازات و فروتنان را پاداش می‌دهند."),
            StoryParagraph("But the novel is not just satire; it is also, and more importantly, a meditation on good and evil, on love and loyalty, on art and courage, on life and death.", "اما رمان تنها هجا نیست؛ همچنین، و مهم‌تر، مراقبه‌ای است درباره خوب و بد، درباره عشق و وفاداری، درباره هنر و شجاعت، درباره زندگی و مرگ."),
            StoryParagraph("At its heart are two stories, intertwined like the threads of a single rope.", "در قلبش دو داستان است، درهم‌بافته چون رشته‌های یک طناب."),
            StoryParagraph("The first is the story of the Master and Margarita: a writer who is destroyed by critics and a woman who loves him so much that she will do anything — anything — to save him.", "اولی داستان استاد و مارگاریتاست: نویسنده‌ای که توسط منتقدان نابود می‌شود و زنی که اینقدر دوستش دارد که هر کاری — هر کاری — برای نجاتش می‌کند."),
            StoryParagraph("The second is the story of Pontius Pilate and Yeshua Ha-Notsri: the Roman procurator who condemns an innocent man to death and the wandering philosopher who forgives him.", "دومی داستان پونتیوس پیلاطس و یشوع هانوتسری است: والی رومی که مردی بی‌گناه را به مرگ محکوم می‌کند و فیلسوف سرگردانی که می‌بخشدش."),
            StoryParagraph("These two stories are connected in ways that are not always obvious, but that become clearer as the novel progresses.", "این دو داستان به شیوه‌هایی به هم وصلند که همیشه واضح نیستند، اما با پیشرفت رمان واضح‌تر می‌شوند."),
            StoryParagraph("Pilate is a man who has made a terrible choice — the choice of power over conscience, of order over justice, of comfort over truth.", "پیلاطس مردی است که انتخابی هولناک کرده — انتخاب قدرت بر وجدان، نظم بر عدالت، راحتی بر حقیقت."),
            StoryParagraph("The Master is a man who has made a different choice — the choice of art over safety, of truth over silence, of love over loneliness.", "استاد مردی است که انتخابی متفاوت کرده — انتخاب هنر بر امنیت، حقیقت بر سکوت، عشق بر تنهایی."),
            StoryParagraph("And Margarita is a woman who has made the ultimate choice — the choice to risk everything, to give everything, to sacrifice everything, for the sake of the man she loves.", "و مارگاریتا زنی است که انتخاب نهایی کرده — انتخاب به خطر انداختن همه چیز، دادن همه چیز، قربانی کردن همه چیز، به خاطر مردی که دوستش دارد."),
            StoryParagraph("The novel's central theme is the power of love — not sentimental love, not romantic love, but the deep, enduring, unconditional love that binds human beings to each other.", "مضمون محوری رمان قدرت عشق است — نه عشق احساساتی، نه عشق رمانتیک، بلکه عشق عمیق و پایدار و بی‌قید و شرطی که انسان‌ها را به هم می‌بندد."),
            StoryParagraph("It is Margarita's love that saves the Master; it is Yeshua's love that saves Pilate; it is love, in the end, that saves everyone who is worth saving.", "عشق مارگاریتا است که استاد را نجات می‌دهد؛ عشق یشوع است که پیلاطس را نجات می‌دهد؛ عشق است، در پایان، که هر کسی که ارزش نجات دارد را نجات می‌دهد."),
            StoryParagraph("But the novel also insists that love is not enough; that love must be accompanied by courage, by sacrifice, by the willingness to suffer for the sake of the beloved.", "اما رمان همچنین اصرار می‌کند که عشق کافی نیست؛ عشق باید با شجاعت همراه باشد، با فداکاری، با آمادگی رنج کشیدن به خاطر محبوب."),
            StoryParagraph("Margarita does not just love the Master; she fights for him, she sacrifices for him, she goes through hell for him.", "مارگاریتا تنها استاد را دوست ندارد؛ برایش می‌جنگد، برایش فدا می‌کند، برایش از جهنم می‌گذرد."),
            StoryParagraph("And it is this active love, this love that acts, this love that refuses to give up, that finally wins.", "و این عشق فعال است، این عشقی که عمل می‌کند، این عشقی که از تسلیم شدن امتناع می‌کند، که سرانجام پیروز می‌شود."),
            StoryParagraph("The novel is also, and perhaps most deeply, a novel about courage — the courage to be an artist in a world that does not want artists, the courage to be free in a world that demands conformity.", "رمان همچنین، و شاید عمیق‌ترین، رمانی است درباره شجاعت — شجاعت هنرمند بودن در جهانی که هنرمندان را نمی‌خواهد، شجاعت آزاد بودن در جهانی که همرنگی می‌طلبد."),
            StoryParagraph("The Master writes his novel knowing that it will be rejected; he writes it knowing that he will be attacked; he writes it knowing that it may destroy him.", "استاد رمانش را می‌نویسد با دانستن اینکه رد می‌شود؛ می‌نویسد با دانستن اینکه مورد حمله قرار می‌گیرد؛ می‌نویسد با دانستن اینکه ممکن است نابودش کند."),
            StoryParagraph("And he writes it anyway — because he has to, because he cannot not write it, because the truth must be told.", "و به هر حال می‌نویسدش — چون مجبور است، چون نمی‌تواند ننویسدش، چون حقیقت باید گفته شود."),
            StoryParagraph("This is the courage of the artist, and it is perhaps the highest form of courage there is: the courage to create, in the face of everything that would silence you.", "این شجاعت هنرمند است و شاید بالاترین شکل شجاعتی است که وجود دارد: شجاعت آفریدن، در برابر هر چیزی که ساکتت می‌کند."),
            StoryParagraph("And the novel itself is an act of this courage — written in secret, written in defiance, written in the face of censorship and persecution.", "و خود رمان عملی از این شجاعت است — پنهانی نوشته شده، در نافرمانی نوشته شده، در برابر سانسور و آزار نوشته شده."),
            StoryParagraph("The novel is, in this sense, its own subject; it is what it is about.", "رمان از این نظر موضوع خودش است؛ آن چیزی است که درباره‌اش است."),
            StoryParagraph("Bulgakov wrote it knowing he could not publish it; the Master writes his novel knowing it will be rejected; and both of them write anyway — because the writing itself is the point.", "بولگاکف نوشتش با دانستن اینکه نمی‌تواند منتشرش کند؛ استاد رمانش را می‌نویسد با دانستن اینکه رد می‌شود؛ و هر دو به هر حال می‌نویسند — چون خودِ نوشتن نکته است."),
            StoryParagraph("There is one more theme that runs through the novel, and it is perhaps the deepest of all: the theme of forgiveness.", "مضمون دیگری هم در رمان جریان دارد و شاید عمیق‌ترین از همه باشد: مضمون بخشش."),
            StoryParagraph("Yeshua forgives Pilate; the Master forgives those who destroyed him; Margarita forgives the Master for giving up; and even Woland, the devil himself, forgives those who deserve forgiveness.", "یشوع پیلاطس را می‌بخشد؛ استاد کسانی که نابودش کردند را می‌بخشد؛ مارگاریتا استاد را برای تسلیم شدنش می‌بخشد؛ و حتی ولاند، خود شیطان، کسانی که سزاوار بخششاند را می‌بخشد."),
            StoryParagraph("Forgiveness is not weakness; it is not surrender; it is not forgetting. Forgiveness is the highest form of strength — the strength to let go of hatred, of resentment, of the desire for revenge.", "بخشش ضعف نیست؛ تسلیم نیست؛ فراموش کردن نیست. بخشش بالاترین شکل قدرت است — قدرت رها کردن نفرت، کینه، میل به انتقام."),
            StoryParagraph("And in this novel, forgiveness is what finally heals; forgiveness is what finally saves; forgiveness is what finally gives peace.", "و در این رمان، بخشش سرانجام شفا می‌دهد؛ بخشش سرانجام نجات می‌دهد؛ بخشش سرانجام آرامش می‌بخشد."),
            StoryParagraph("The Master and Margarita is not an easy novel; it is long, and complex, and full of digressions and complications.", "استاد و مارگاریتا رمان آسانی نیست؛ طولانی است و پیچیده و پر از انحراف‌ها و پیچیدگی‌ها."),
            StoryParagraph("But it is a novel that rewards patience and attention with something rare: a vision of the world that is both honest and hopeful, both tragic and joyful, both human and divine.", "اما رمانی است که صبر و توجه را با چیزی نادر پاداش می‌دهد: بینشی از جهان که هم صادق است و هم امیدوار، هم تراژیک و هم شادمانه، هم انسانی و هم الهی."),
            StoryParagraph("It is a novel about the devil, and about God; about evil, and about good; about the darkness in the human heart, and about the light that can shine even there.", "رمانی است درباره شیطان و درباره خدا؛ درباره شر و درباره خوبی؛ درباره تاریکی قلب انسانی و درباره نوری که حتی آنجا می‌تواند بدرخشد."),
            StoryParagraph("It is a novel about Moscow in the 1930s, and about Jerusalem in the first century, and about the eternal struggle between power and conscience.", "رمانی است درباره مسکوی دهه ۱۹۳۰ و درباره اورشلیم قرن اول و درباره کشمکش جاودان میان قدرت و وجدان."),
            StoryParagraph("And it is a novel about a woman named Margarita, who loved a man named the Master, and who went through hell to bring him back.", "و رمانی است درباره زنی به نام مارگاریتا، که مردی به نام استاد را دوست داشت و از جهنم گذشت تا بازش گرداند."),
            StoryParagraph("Her love is the heart of the novel; her courage is its soul; her willingness to sacrifice is its meaning.", "عشق او قلب رمان است؛ شجاعتش روحش؛ آمادگی‌اش برای فداکاری معنایش."),
            StoryParagraph("For in the end, the novel says, it is not power that saves us, nor wealth, nor fame, nor even art.", "زیرا در پایان، رمان می‌گوید، نه قدرت نجاتمان می‌دهد، نه ثروت، نه شهرت، نه حتی هنر."),
            StoryParagraph("It is love — real love, active love, sacrificial love — that saves us; and it is only by loving that we can be saved.", "عشق است — عشق واقعی، عشق فعال، عشق فداکار — که نجاتمان می‌دهد؛ و تنها با عشق ورزیدن می‌توانیم نجات یابیم."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of the Master and Margarita does not end with the last page; it begins there, in the heart of every reader who has been touched by it.", "زیرا داستان استاد و مارگاریتا با صفحه آخر پایان نمی‌یابد؛ آنجا آغاز می‌شود، در قلب هر خواننده‌ای که توسط آن لمس شده."),
            StoryParagraph("And every reader who has been touched by it, has been changed by it; and every reader who has been changed by it, will never be the same.", "و هر خواننده‌ای که توسط آن لمس شده، توسط آن تغییر یافته؛ و هر خواننده‌ای که توسط آن تغییر یافته، هرگز همان نخواهد بود."),
            StoryParagraph("Manuscripts don't burn.", "دست‌نوشته‌ها نمی‌سوزند."),
            StoryParagraph("This is the novel's most famous line, and it is also its deepest truth.", "این مشهورترین جمله رمان است و همچنین عمیق‌ترین حقیقتش."),
            StoryParagraph("The Master burned his manuscript, but it survived; Bulgakov's novel was censored, but it survived; truth may be suppressed, but it cannot be destroyed.", "استاد دست‌نوشته‌اش را سوزاند اما زنده ماند؛ رمان بولگاکف سانسور شد اما زنده ماند؛ حقیقت ممکن است سرکوب شود اما نمی‌توان نابودش کرد."),
            StoryParagraph("And the same is true of love, and of courage, and of everything that is truly human.", "و همین درست است درباره عشق و شجاعت و هر چیزی که واقعاً انسانی است."),
            StoryParagraph("These things may be hidden, may be silenced, may be burned; but they cannot be destroyed.", "این چیزها ممکن است پنهان شوند، ممکن است ساکت شوند، ممکن است سوزانده شوند؛ اما نمی‌توان نابودشان کرد."),
            StoryParagraph("They survive, as the Master's novel survived, as Margarita's love survived, as Bulgakov's own book survived.", "زنده می‌مانند، همانطور که رمان استاد زنده ماند، همانطور که عشق مارگاریتا زنده ماند، همانطور که کتاب خود بولگاکف زنده ماند."),
            StoryParagraph("They survive, and they wait, and they find their readers, their lovers, their believers.", "زنده می‌مانند و منتظر می‌مانند و خوانندگانشان را می‌یابند، عاشقانشان را، باورکنندگانشان را."),
            StoryParagraph("And so the novel ends, as all great novels must end — not with a conclusion, but with a beginning; not with an answer, but with a hope.", "و اینگونه رمان پایان می‌یابد، همانطور که همه رمان‌های بزرگ باید پایان یابند — نه با نتیجه‌گیری، بلکه با آغازی؛ نه با پاسخی، بلکه با امیدی."),
            StoryParagraph("The hope that love is stronger than death; the hope that courage is stronger than fear; the hope that truth is stronger than lies.", "امید اینکه عشق از مرگ قوی‌تر است؛ امید اینکه شجاعت از ترس قوی‌تر؛ امید اینکه حقیقت از دروغ قوی‌تر."),
            StoryParagraph("The hope that manuscripts don't burn; that love doesn't end; that goodness, in the end, prevails.", "امید اینکه دست‌نوشته‌ها نمی‌سوزند؛ عشق تمام نمی‌شود؛ خوبی، در پایان، چیره می‌شود."),
            StoryParagraph("This is the message of The Master and Margarita.", "این پیام استاد و مارگاریتاست."),
            StoryParagraph("And it is a message worth believing.", "و پیامی است که ارزش باور کردن دارد.")
        )
    )
}